/// <summary>
/// Header service for the multithreaded batch monitoring test job.
/// Queues CustTable records into METBatchMonitoringTestQueue for parallel task processing.
/// </summary>
class METBatchMonitoringMultiTestService extends METSysOperationService
{
    private guid        topProcessId;

}

Method.Source:
/// <summary>
/// Entry point called by the controller.
/// </summary>
public void process(METBatchMonitoringMultiTestContract _contract)
{
    this.processInternal(_contract);
}

public void initialise()
{
    super();

    METBatchMonitoringMultiTestContract contract = dataContract as METBatchMonitoringMultiTestContract;
    this.executeOperation(contract);
}

protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METBatchMonitoringMultiTestContract();
}

protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);

    METBatchMonitoringMultiTestContract contract = _taskDataContract as METBatchMonitoringMultiTestContract;
    contract.parmTopProcessId(topProcessId);
}

/// <summary>
/// Queues CustTable records into METBatchMonitoringTestQueue for task threads to drain.
/// Wraps the loop with a procMetrics header log entry.
/// </summary>
public void executeOperation(METBatchMonitoringMultiTestContract _contract)
{
    RecordInsertList            queueRecordList;
    METBatchMonitoringTestQueue queueEntry;
    CustTable                   custTable;
    QueryRun                    queryRun;
    Query                       query = new Query();
    QueryBuildDataSource        qbds  = query.addDataSource(tableNum(CustTable));
    int                         queuedCount;
    int                         maxRecordsParam = _contract.parmMaxRecords();
    METProcMetrics              procMetrics;

    METBatchMonitoringTestQueue::cleanUp();
    queueRecordList = new RecordInsertList(tableNum(METBatchMonitoringTestQueue));
    topProcessId    = newGuid();

    if (_contract.parmInventLocationId())
    {
        SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, InventLocation)).value(_contract.parmInventLocationId());
    }

    queryRun = new QueryRun(query);

    procMetrics = METProcMetrics::construct(METBatchLogOperation::METBatchMonitoringTest);

    if (maxRecordsParam > 0)
    {
        procMetrics.setTotalCount(maxRecordsParam);
    }
    else
    {
        procMetrics.setTotalCountFromQuery(new QueryRun(query));
    }

    procMetrics.beginTrace('Test job multi: queuing customers');

    try
    {
        while (queryRun.next())
        {
            custTable = queryRun.get(tableNum(CustTable));

            queueEntry.clear();
            queueEntry.ProcessId   = topProcessId;
            queueEntry.CustAccount = custTable.AccountNum;
            queueRecordList.add(queueEntry);

            queuedCount++;
            procMetrics.incProcessedCount();

            if (maxRecordsParam > 0 && queuedCount >= maxRecordsParam)
            {
                break;
            }
        }

        queueRecordList.insertDatabase();

        procMetrics.endTrace(strFmt('Customers queued: %1', queuedCount));
    }
    catch
    {
        procMetrics.endTrace(strFmt('Queuing failed after %1 customers', queuedCount), METBatchMonitoringStatus::Failed);
        throw;
    }
}
